  1	/**
  2	 * The `--witness` stage of `migrate`.
  3	 *
  4	 * It is opt-in for exactly the reason `--install`, `--build`, `--ingest` and
  5	 * `--era-cell` are: a run that did not ask for it gets a record saying the lane
  6	 * was not witnessed, rather than a record whose silence a reader could take for
  7	 * a lane that was. It is ordered after the build because there is nothing to
  8	 * witness until something has been emitted.
  9	 *
 10	 * The stage invokes exactly the path `witness:real-app` invokes. It composes no
 11	 * journey of its own and forks no runner: the driver selection, the serialized
 12	 * replay and the locality gate are all the generic runner's.
 13	 */
 14	
 15	import * as path from 'pathe';
 16	import type { WitnessSynthesizedRealAppRecord } from '../../../core/src/receipts/witness-real-app.ts';
 17	import { witnessBrowserNotProvisioned } from '../witness/browser.ts';
 18	import { refuse } from './refusals.ts';
 19	
 20	export type WitnessRecord = Readonly<{
 21		ran: boolean;
 22		/** Why the stage did not run, when it did not. */
 23		reason?: string;
 24		journeySource?: WitnessSynthesizedRealAppRecord['journeySource'];
 25		replayabilityRatio?: number;
 26		journeysRun?: number;
 27		digest?: string;
 28		notEstablished: readonly string[];
 29	}>;
 30	
 31	const NOT_REQUESTED_NOT_ESTABLISHED: readonly string[] = Object.freeze([
 32		'The lane was not witnessed. Nothing in this record establishes that anything renders, that any route is reachable, or that any gesture the application offers still works after the migration.',
 33	]);
 34	
 35	const RAN_NOT_ESTABLISHED: readonly string[] = Object.freeze([
 36		'A witnessed lane is a lane whose declared journeys were replayed once each on this host, serialized. Nothing here establishes an outcome under concurrent load.',
 37		'Where the journeys were synthesized, they were derived from the application own end-to-end suite or from a bounded loopback crawl. The replayability ratio in the record is a count of derived journeys that name a route to start from, not a measure of coverage.',
 38	]);
 39	
 40	export function witnessNotRequested(reason: string): WitnessRecord {
 41		return Object.freeze({ ran: false, reason, notEstablished: NOT_REQUESTED_NOT_ESTABLISHED });
 42	}
 43	
 44	/**
 45	 * Run the witness body, and name the one condition that is about this host.
 46	 *
 47	 * A host with no provisioned browser is not a defect in the application and not
 48	 * a defect in the pipeline: it is a declaration nobody made. It is raised here,
 49	 * inside the operator surface, so the census can count it and a fleet report can
 50	 * tally it — the resolver itself lives under `witness/` and stays free of the
 51	 * refusal carrier.
 52	 */
 53	async function witnessing<T>(body: () => Promise<T>): Promise<T> {
 54		try {
 55			return await body();
 56		} catch (error) {
 57			const missing = witnessBrowserNotProvisioned(error);
 58			if (missing === null) throw error;
 59			refuse({
 60				code: 'witness.browser-not-provisioned',
 61				message: missing.message,
 62				stage: 'witness',
 63				origin: 'pipeline',
 64			});
 65		}
 66	}
 67	
 68	/**
 69	 * Witness the built lane.
 70	 *
 71	 * The runner is imported lazily, because it pulls in a browser host and a static
 72	 * server that a `migrate` run which never declared `--witness` has no business
 73	 * loading.
 74	 */
 75	export async function runLaneWitness(options: {
 76		application: string;
 77		sourceRoot: string;
 78		laneBuild: string;
 79		baselineBuild?: string;
 80	}): Promise<WitnessRecord> {
 81		const { runSynthesizedWitnessRealApp, synthesizedWitnessOutputDir } =
 82			await import('../witness/real-app-run.ts');
 83		const record = await witnessing(async () =>
 84			runSynthesizedWitnessRealApp({
 85				application: options.application,
 86				framework: 'react',
 87				declaration: 'default',
 88				sourceRoot: options.sourceRoot,
 89				lanes:
 90					options.baselineBuild === undefined
 91						? [{ lane: 'migrated' as const, laneRoot: path.resolve(options.laneBuild) }]
 92						: [
 93								{
 94									lane: 'baseline' as const,
 95									laneRoot: path.resolve(options.baselineBuild),
 96								},
 97								{
 98									lane: 'migrated' as const,
 99									laneRoot: path.resolve(options.laneBuild),
100								},
101							],
102				output: synthesizedWitnessOutputDir(options.application),
103			}),
104		);
105		return Object.freeze({
106			ran: true,
107			journeySource: record.journeySource,
108			replayabilityRatio: record.synthesized.replayabilityRatio,
109			journeysRun: record.execution.journeysRun,
110			digest: record.integrity.canonicalDigest,
111			notEstablished: RAN_NOT_ESTABLISHED,
112		});
113	}

