308		if (halted !== null) {
309			const at = new Date().toISOString();
310			state.rows.push(
311				Object.freeze({
312					name,
313					status: 'not-run' as const,
314					reason: notRunBecause(halted.stage, halted.status),
315					startedAt: at,
316					endedAt: at,
317				}),
318			);
319			return null;
320		}
321		const startedAt = new Date().toISOString();
322		try {
323			const value = await stage();
324			state.rows.push(
325				Object.freeze({
326					name,
327					status: 'ran' as const,
328					record: value,
329					startedAt,
330					endedAt: new Date().toISOString(),
331				}),
332			);
333			return value;
334		} catch (error) {
335			const endedAt = new Date().toISOString();
336			const refusal = pipelineRefusalOf(error);
