549		return plan.map(
550			(row, index) =>
551				`  ${String(index + 1)}. ${row.name.padEnd(STAGE_COLUMN)}${
552					row.forwards.length === 0
553						? 'no declaration from this command line'
554						: row.forwards.join(' ')
555				}`,
556		);
557	}
