563			`lane: ${record.lane}`,
564			`acquisition root: ${record.roots.source}`,
565			`frontend root: ${record.roots.frontend} (${record.roots.frontendSource})`,
566			`frontend root basis: ${record.roots.frontendBasis}`,
567			'',
