571			lines.push('');
572			lines.push(...renderStagePlan(record.stagePlan));
573			lines.push('');
574			lines.push('No stage ran and nothing was written into the lane.');
575		} else {
576			for (const row of record.stages)
577				lines.push(
578					`  ${row.name.padEnd(STAGE_COLUMN)}${row.status.padEnd(10)}${row.reason ?? ''}`,
579				);
580			lines.push('');
581			lines.push(
582				record.outcome === 'proceeded'
583					? `all ${String(record.stages.length)} stage(s) proceeded.`
584					: record.outcome === 'refused'
585						? `stopped at ${record.refusal?.stage ?? ''}.`
586						: `stopped at ${record.defect?.stage ?? ''} with a defect.`,
587			);
588		}
589		lines.push('');
590		if (record.refusal !== undefined) lines.push(renderRefusal(record.refusal));
591		if (record.defect !== undefined) {
592			lines.push(`defect: ${record.defect.stage}`);
593			lines.push('');
594			lines.push(record.defect.message);
595			lines.push('');
596		}
