598			record.report.status === 'emitted'
599				? `report: emitted at ${record.report.path} (${record.report.digest})`
600				: `report: ${record.report.status} (${record.report.slot}) — ${record.report.reason}`,
601		);
602		lines.push('');
603		for (const line of record.notEstablished) lines.push(`not established: ${line}`);
