7732					digests.push(run.semanticDigest);
7733					journeys.push({
7734						name: emission.name,
7735						source: emission.source,
7736						specFile: emission.specFile,
7737						replayable: true,
7738						ran: true,
7739						routesDeclared: emission.plan.routes.length,
7740						routesReached: measured.routesReached,
7741						selectorsDeclared: emission.plan.selectors.length,
7742						selectorsPresent: measured.selectorsPresent,
7743						routesWithoutOverflow: measured.routesWithoutOverflow,
7744						outcomes: [...run.assertions],
7745					});
7746				}
7747				laneRecords.push({
7748					lane: lane.lane,
7749					journeys,
7750					successfulNonLoopback: 0,
7751					semanticDigest: sha256(canonicalize(digests)),
7752				});
7753			}
7754			tally = {
7755				total: emissions.length,
7756				replayable: replayable.length,
7757				ran: ranJourneys.size,
7758				replayabilityRatio: witnessReplayabilityRatio(replayable.length, emissions.length),
