7761		}
7762		const record: WitnessSynthesizedRealAppRecord = {
7763			schemaVersion: WITNESS_SYNTHESIZED_REAL_APP_SCHEMA,
7764			flow: 'witness-real-app-synthesized',
7765			application: options.application,
7766			framework: options.framework,
