7773				lanesRun: laneRecords.length,
7774				journeysRun: laneRecords.reduce(
7775					(sum, lane) => sum + lane.journeys.filter((journey) => journey.ran).length,
7776					0,
7777				),
7778			},
7779			locality: { mode: 'offline', successfulNonLoopback: 0, osWideIsolation: false },
7780			notEstablished: [...WITNESS_SYNTHESIZED_NOT_ESTABLISHED],
7781			integrity: { algorithm: 'sha256', canonicalDigest: '' },
7782		};
