 880	async function readStaticFile(file: string): Promise<{ file: string; body: Buffer } | null> {
 881		const details = await lstat(file).catch(() => null);
 882		if (details === null || details.isSymbolicLink()) return null;
 883		const resolved = details.isDirectory() ? join(file, 'index.html') : file;
 884		const resolvedDetails = await lstat(resolved).catch(() => null);
 885		if (resolvedDetails === null || !resolvedDetails.isFile() || resolvedDetails.isSymbolicLink())
 886			return null;
 887		return { file: resolved, body: await readFile(resolved) };
 888	}
