 904	async function collectRequestBody(request: IncomingMessage): Promise<Buffer | null> {
 905		const chunks: Buffer[] = [];
 906		let bytes = 0;
 907		for await (const chunk of request as AsyncIterable<Buffer | string>) {
 908			const buffer = typeof chunk === 'string' ? Buffer.from(chunk, 'utf8') : chunk;
 909			bytes += buffer.length;
 910			if (bytes > MAX_API_REQUEST_BYTES) return null;
 911			chunks.push(buffer);
 912		}
 913		return Buffer.concat(chunks);
 914	}
