     2	export const ANGULAR_CLI_BINARY = 'ng';
     3	
     4	/**
     5	 * A flag the Angular CLI stopped parsing, and what it became.
---
   170	
   171	/** camelCase as a command-line flag spells it: `extractCss` -> `--extract-css`. */
   172	export function optionFlagSpelling(option: string): string {
   173		let spelled = '';
   174		for (const character of option) {
   175			const lower = character.toLowerCase();
   176			if (lower !== character) spelled += '-';
   177			spelled += lower;
   178		}
   179		return `--${spelled}`;
   180	}
   181	
   182	/**
   183	 * The flags whose builder option *this* workspace migration removed.
   184	 *
   185	 * Read from the migration's own changes so the set is a fact about this
   186	 * workspace: an option the era document never declared is not in it, and a
   187	 * script that passes the matching flag anyway is left alone and reported. The
   188	 * change has to be a removal (`to === null`) of a key the builder schema is
   189	 * known to have dropped, which is what keeps an unrelated removal — a
   190	 * `defaultProject`, a lint target — from inventing a flag rule.
   191	 */
   192	export function removedBuilderOptionFlags(
   193		changes: readonly ConfigChange[],
   194	): Readonly<Record<string, string>> {
   195		const flags: Record<string, string> = {};
   196		for (const change of changes) {
   197			if (change.to !== null) continue;
   198			const option = change.path.split('.').at(-1) ?? '';
   199			if (!REMOVED_BUILDER_OPTIONS.includes(option)) continue;
   200			flags[optionFlagSpelling(option)] = change.path;

